// guardedDial preserves the platform socket-control behavior while deliberately
// avoiding netns.NewDialer's environment SOCKS wrapper, DNS caches, URL dialer
// overrides and HTTP proxy setup. Policy parses and checks the numeric endpoint.
func (c *Client) guardedDial(ctx context.Context, network, address string) (net.Conn, error) {
