func TestUnderlayGuardNativeLoopbackTCP(t *testing.T) {
	if os.Getenv("SOBALINK_RUN_UNDERLAY_NATIVE") != "1" {
		t.Skip("explicit native loopback opt-in required")
	}
	for _, family := range []struct{ network, address, prefix string }{{"tcp4", "127.0.0.1:0", "127.0.0.1/32"}, {"tcp6", "[::1]:0", "::1/128"}} {
		t.Run(family.network, func(t *testing.T) {
			ln, err := net.ListenTCP(family.network, net.TCPAddrFromAddrPort(netip.MustParseAddrPort(family.address)))
			if err != nil {
				t.Fatal(err)
			}
			defer ln.Close()
			forbidden, err := net.ListenTCP(family.network, net.TCPAddrFromAddrPort(netip.MustParseAddrPort(family.address)))
			if err != nil {
				t.Fatal(err)
			}
			defer forbidden.Close()
			p := derpGuardPolicy(t, family.prefix, ln.Addr().String())
			c := &Client{UnderlayPolicy: p, netMon: netmon.NewStatic(), logf: logger.Discard, clock: tstime.StdClock{}}
			c.SetURLDialer(func(context.Context, string, string) (net.Conn, error) {
				t.Error("guard bypassed by custom dialer")
				return nil, nil
			})
			var clients, peers []net.Conn
			for _, viaURL := range []bool{true, false} {
				dial := func(address string) (net.Conn, error) {
					if viaURL {
						c.url = &url.URL{Scheme: "https", Host: address}
						return c.dialURL(context.Background())
					}
					ap := netip.MustParseAddrPort(address)
					n := &tailcfg.DERPNode{HostName: "synthetic.invalid", IPv4: "none", IPv6: "none", DERPPort: int(ap.Port())}
					if ap.Addr().Is4() {
						n.IPv4 = ap.Addr().String()
					} else {
						n.IPv6 = ap.Addr().String()
					}
					nc, _, e := c.dialRegion(context.Background(), &tailcfg.DERPRegion{Nodes: []*tailcfg.DERPNode{n}})
					return nc, e
				}
				conn, err := dial(ln.Addr().String())
				if err != nil {
					t.Fatal(err)
				}
				ln.SetDeadline(time.Now().Add(time.Second))
				peer, err := ln.AcceptTCP()
				if err != nil {
					t.Fatal(err)
				}
				defer peer.Close()
				defer conn.Close()
				clients = append(clients, conn)
				peers = append(peers, peer)
				if nc, err := dial(forbidden.Addr().String()); !errors.Is(err, underlayguard.ErrDenied) {
					if nc != nil {
						nc.Close()
					}
					t.Fatal(err)
				}
			}
			p.Revoke()
			for _, conn := range clients {
				if _, err := conn.Write([]byte("revoked")); !errors.Is(err, underlayguard.ErrRevoked) {
					t.Fatal("live TCP write retained authority", err)
				}
			}
			for _, peer := range peers {
				peer.SetReadDeadline(time.Now().Add(time.Second))
				if _, err := peer.Read(make([]byte, 1)); !errors.Is(err, io.EOF) {
					t.Fatal("live TCP socket did not close on revoke", err)
				}
			}
			if _, err := c.dialContext(context.Background(), family.network, ln.Addr().String()); !errors.Is(err, underlayguard.ErrRevoked) {
				t.Fatal(err)
			}
			forbidden.SetDeadline(time.Now().Add(50 * time.Millisecond))
			if nc, err := forbidden.AcceptTCP(); err == nil {
				nc.Close()
				t.Fatal("unapproved socket accepted")
			} else if ne, ok := err.(net.Error); !ok || !ne.Timeout() {
				t.Fatal("negative receiver did not time out", err)
			}
		})
	}
}

