// Package underlayguard provides a per-engine numeric destination boundary.
// It does not prove the selected interface, on-link routing, or VPN containment.
package underlayguard

import (
	"context"
	"errors"
	"io"
	"net"
	"net/netip"
	"slices"
	"sync"
	"sync/atomic"
)

// APIVersion identifies the constructor-wired adaptation expected by consumers.
const APIVersion = 1

var (
	ErrDenied              = errors.New("underlay destination denied")
	ErrRevoked             = errors.New("underlay policy revoked")
	ErrDiagnosticsDisabled = errors.New("underlay diagnostics disabled")
)

// Config selects the only permitted UDP prefixes and exact TCP relay endpoints.
// Prefixes must be canonical, wholly private or wholly loopback, and unzoned.
// Each relay must be covered by a selected prefix. Slices are copied by New.
type Config struct {
	Prefixes []netip.Prefix
	Relays   []netip.AddrPort
}

// Policy is immutable after construction except for permanent revocation.
// A non-nil zero Policy denies everything; a nil Policy preserves normal mode.
// Do not copy Policy after use. Give every engine generation its own Policy.
type Policy struct {
	prefixes   []netip.Prefix
	relays     []netip.AddrPort
	valid      bool
	gate       sync.RWMutex
	revoked    atomic.Bool
	revokeOnce sync.Once
	ctx        context.Context
	cancel     context.CancelFunc
	connsMu    sync.Mutex
	conns      map[*guardedConn]struct{}
	udp        map[*udpRegistration]struct{}
}

func New(cfg Config) (*Policy, error) {
	if len(cfg.Prefixes) == 0 || len(cfg.Relays) == 0 {
		return nil, ErrDenied
	}
	p := &Policy{prefixes: slices.Clone(cfg.Prefixes), relays: slices.Clone(cfg.Relays), conns: make(map[*guardedConn]struct{}), udp: make(map[*udpRegistration]struct{})}
	for _, prefix := range p.prefixes {
		if !prefix.IsValid() || prefix != prefix.Masked() || prefix.Bits() == 0 || prefix.Addr().Is4In6() || prefix.Addr().Zone() != "" {
			return nil, ErrDenied
		}
		b := prefix.Addr().AsSlice()
		for bit := prefix.Bits(); bit < len(b)*8; bit++ {
			b[bit/8] |= 1 << (7 - bit%8)
		}
		last, _ := netip.AddrFromSlice(b)
		if !(prefix.Addr().IsPrivate() && last.IsPrivate()) && !(prefix.Addr().IsLoopback() && last.IsLoopback()) {
			return nil, ErrDenied
		}
	}
	for _, relay := range p.relays {
		if !p.permitsUDP(relay) {
			return nil, ErrDenied
		}
	}
	p.ctx, p.cancel = context.WithCancel(context.Background())
	p.valid = true
	return p, nil
}

func validAddress(ap netip.AddrPort) bool {
	a := ap.Addr()
	return ap.IsValid() && ap.Port() != 0 && a.Zone() == "" && !a.Is4In6() && (a.IsPrivate() || a.IsLoopback()) && !a.IsUnspecified() && !a.IsMulticast()
}

func (p *Policy) permitsUDP(ap netip.AddrPort) bool {
	if !validAddress(ap) {
		return false
	}
	for _, prefix := range p.prefixes {
		if prefix.Contains(ap.Addr()) {
			return true
		}
	}
	return false
}

// Validate rejects missing construction or permanent revocation.
// A nil policy is the explicit unrestricted mode used by ordinary Tailnet.
func (p *Policy) Validate() error {
	if p == nil {
		return nil
	}
	if !p.valid {
		return ErrDenied
	}
	if p.revoked.Load() {
		return ErrRevoked
	}
	return nil
}

// DoUDP holds admission through one actual write, including a batch write.
// Call it again for every retry and every single-write batch fallback.
// write must run synchronously and must not call Revoke itself.
func (p *Policy) DoUDP(ap netip.AddrPort, write func() error) error {
	if p == nil {
		return write()
	}
	if err := p.Validate(); err != nil {
		return err
	}
	p.gate.RLock()
	defer p.gate.RUnlock()
	if err := p.Validate(); err != nil {
		return err
	}
	if !p.permitsUDP(ap) {
		return ErrDenied
	}
	return write()
}

type udpRegistration struct{ io.Closer }

// TrackUDP registers the actual underlying socket before it is published.
// Revoke closes it before draining admitted writes, interrupting blocked writes.
// The returned function unregisters it after its normal Close. On rejection the
// supplied socket is closed immediately. Nil preserves ordinary mode.
func (p *Policy) TrackUDP(socket io.Closer) (func(), error) {
	if p == nil {
		return func() {}, nil
	}
	p.connsMu.Lock()
	if err := p.Validate(); err != nil {
		p.connsMu.Unlock()
		socket.Close()
		return func() {}, err
	}
	r := &udpRegistration{socket}
	p.udp[r] = struct{}{}
	p.connsMu.Unlock()
	return func() { p.connsMu.Lock(); delete(p.udp, r); p.connsMu.Unlock() }, nil
}

// DialContext permits only an exact numeric relay and matching TCP family.
// dial must be a direct, context-aware socket dialer, never a proxy or resolver.
// The returned connection denies writes after revocation and is closed by Revoke.
func (p *Policy) DialContext(ctx context.Context, network, address string, dial func(context.Context, string, string) (net.Conn, error)) (net.Conn, error) {
	if p == nil {
		return dial(ctx, network, address)
	}
	if err := p.Validate(); err != nil {
		return nil, err
	}
	ap, err := netip.ParseAddrPort(address)
	if err != nil || !validAddress(ap) || !slices.Contains(p.relays, ap) ||
		(network != "tcp" && network != "tcp4" && network != "tcp6") ||
		(network == "tcp4" && !ap.Addr().Is4()) || (network == "tcp6" && !ap.Addr().Is6()) {
		return nil, ErrDenied
	}
	p.gate.RLock()
	defer p.gate.RUnlock()
	if err := p.Validate(); err != nil {
		return nil, err
	}
	dialCtx, cancel := context.WithCancel(ctx)
	stop := context.AfterFunc(p.ctx, cancel)
	defer stop()
	defer cancel()
	nc, err := dial(dialCtx, network, ap.String())
	if err != nil {
		if nc != nil {
			nc.Close()
		}
		return nil, err
	}
	if nc == nil {
		return nil, ErrDenied
	}
	if err := p.Validate(); err != nil {
		nc.Close()
		return nil, err
	}
	c := &guardedConn{Conn: nc, policy: p}
	p.connsMu.Lock()
	p.conns[c] = struct{}{}
	p.connsMu.Unlock()
	return c, nil
}

// Revoke permanently rejects new admissions, cancels pending dials, waits for
// admitted writes and dials to finish, and closes every admitted TCP connection.
// On return, no policy-admitted write or dial is still in flight. It cannot
// recall packets already accepted by the operating system. Calls are idempotent.
func (p *Policy) Revoke() {
	if p == nil {
		return
	}
	p.revokeOnce.Do(func() {
		p.revoked.Store(true)
		if p.cancel != nil {
			p.cancel()
		}
		// Closing already registered connections interrupts blocked writes
		// before waiting for their admission locks. A dial that raced this
		// snapshot is covered by the second close after the gate drains.
		p.closeConnections()
		p.gate.Lock()
		p.gate.Unlock()
		p.closeConnections()
	})
}

func (p *Policy) closeConnections() {
	p.connsMu.Lock()
	conns := make([]*guardedConn, 0, len(p.conns))
	for c := range p.conns {
		conns = append(conns, c)
	}
	udp := make([]*udpRegistration, 0, len(p.udp))
	for c := range p.udp {
		udp = append(udp, c)
		delete(p.udp, c)
	}
	p.connsMu.Unlock()
	for _, c := range udp {
		c.Close()
	}
	for _, c := range conns {
		c.Close()
	}
}

type guardedConn struct {
	net.Conn
	policy   *Policy
	once     sync.Once
	closeErr error
}

func (c *guardedConn) Write(b []byte) (int, error) {
	if err := c.policy.Validate(); err != nil {
		return 0, err
	}
	c.policy.gate.RLock()
	defer c.policy.gate.RUnlock()
	if err := c.policy.Validate(); err != nil {
		return 0, err
	}
	return c.Conn.Write(b)
}

func (c *guardedConn) Close() error {
	c.once.Do(func() {
		c.closeErr = c.Conn.Close()
		c.policy.connsMu.Lock()
		delete(c.policy.conns, c)
		c.policy.connsMu.Unlock()
	})
	return c.closeErr
}

