func testConfig() Config {
	return Config{Prefixes: []netip.Prefix{netip.MustParsePrefix("10.25.0.0/24"), netip.MustParsePrefix("fd25::/64")}, Relays: []netip.AddrPort{netip.MustParseAddrPort("10.25.0.2:443"), netip.MustParseAddrPort("[fd25::2]:443")}}
}
func testPolicy(t *testing.T) *Policy {
	t.Helper()
	p, err := New(testConfig())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(p.Revoke)
	return p
}

func TestPolicyValidationAndImmutableCopy(t *testing.T) {
	cfg := testConfig()
	p, err := New(cfg)
	if err != nil {
		t.Fatal(err)
	}
	defer p.Revoke()
	cfg.Prefixes[0] = netip.MustParsePrefix("10.26.0.0/24")
	cfg.Relays[0] = netip.MustParseAddrPort("10.26.0.2:443")
	for _, address := range []string{"10.25.0.3:1", "[fd25::3]:65535"} {
		if err := p.DoUDP(netip.MustParseAddrPort(address), func() error { return nil }); err != nil {
			t.Fatal(address, err)
		}
	}
	for _, address := range []string{"10.26.0.3:443", "192.0.2.3:443", "8.8.8.8:443", "10.25.0.3:0", "[::ffff:10.25.0.3]:443", "[fd25::3%zone]:443", "[fd26::3]:443", "[ff02::1]:443"} {
		called := false
		err := p.DoUDP(netip.MustParseAddrPort(address), func() error { called = true; return nil })
		if !errors.Is(err, ErrDenied) || called {
			t.Fatalf("%s: error=%v called=%v", address, err, called)
		}
	}
	for _, prefix := range []string{"0.0.0.0/0", "10.25.0.1/24", "10.0.0.0/7", "172.0.0.0/8", "::/0", "fc00::/6", "::ffff:10.25.0.0/120"} {
		cfg := testConfig()
		cfg.Prefixes = []netip.Prefix{netip.MustParsePrefix(prefix)}
		if _, err := New(cfg); !errors.Is(err, ErrDenied) {
			t.Fatal(prefix, err)
		}
	}
	if _, err := New(Config{}); !errors.Is(err, ErrDenied) {
		t.Fatal(err)
	}
	if _, err := New(Config{Prefixes: []netip.Prefix{netip.MustParsePrefix("127.0.0.0/8"), netip.MustParsePrefix("::1/128")}, Relays: []netip.AddrPort{netip.MustParseAddrPort("127.0.0.1:8443"), netip.MustParseAddrPort("[::1]:8443")}}); err != nil {
		t.Fatal(err)
	}
}

func TestNilAndUninitializedPolicies(t *testing.T) {
	var nilPolicy *Policy
	called := 0
	if err := nilPolicy.DoUDP(netip.AddrPort{}, func() error { called++; return nil }); err != nil || called != 1 {
		t.Fatal(err, called)
	}
	nilPolicy.Revoke()
	var empty Policy
	if err := empty.DoUDP(netip.MustParseAddrPort("10.25.0.3:443"), func() error { called++; return nil }); !errors.Is(err, ErrDenied) || called != 1 {
		t.Fatal(err, called)
	}
	empty.Revoke()
}

func awaitRevoked(t *testing.T, p *Policy) {
	t.Helper()
	deadline := time.Now().Add(3 * time.Second)
	for !p.revoked.Load() {
		if time.Now().After(deadline) {
			t.Fatal("revocation did not start")
		}
		runtime.Gosched()
	}
}

func TestRevokeWaitsForAdmittedUDPAndDeniesRetries(t *testing.T) {
	p := testPolicy(t)
	entered, release, finished := make(chan struct{}), make(chan struct{}), make(chan struct{})
	go func() {
		defer close(finished)
		_ = p.DoUDP(netip.MustParseAddrPort("10.25.0.3:443"), func() error { close(entered); <-release; return nil })
	}()
	<-entered
	done := make(chan struct{})
	go func() { p.Revoke(); close(done) }()
	awaitRevoked(t, p)
	select {
	case <-done:
		t.Fatal("Revoke returned during write")
	default:
	}
	if err := p.DoUDP(netip.MustParseAddrPort("10.25.0.3:443"), func() error { t.Error("retry reached writer"); return nil }); !errors.Is(err, ErrRevoked) {
		t.Fatal(err)
	}
	close(release)
	<-finished
	<-done
	p.Revoke()
