type blockedConn struct {
	entered, closed chan struct{}
	once            sync.Once
	writes, closes  atomic.Int32
}

func (c *blockedConn) Write([]byte) (int, error) {
	c.writes.Add(1)
	close(c.entered)
	<-c.closed
	return 0, net.ErrClosed
}
func (c *blockedConn) Read([]byte) (int, error) { <-c.closed; return 0, net.ErrClosed }
func (c *blockedConn) Close() error {
	c.once.Do(func() { c.closes.Add(1); close(c.closed) })
	return nil
}
func (c *blockedConn) LocalAddr() net.Addr              { return &net.TCPAddr{} }
func (c *blockedConn) RemoteAddr() net.Addr             { return &net.TCPAddr{} }
func (c *blockedConn) SetDeadline(time.Time) error      { return nil }
func (c *blockedConn) SetReadDeadline(time.Time) error  { return nil }
func (c *blockedConn) SetWriteDeadline(time.Time) error { return nil }

