func newGuardedPolicy(t *testing.T, prefix, relay string) *underlayguard.Policy {
	t.Helper()
	p, e := underlayguard.New(underlayguard.Config{Prefixes: []netip.Prefix{netip.MustParsePrefix(prefix)}, Relays: []netip.AddrPort{netip.MustParseAddrPort(relay)}})
	if e != nil {
