	}
	t.Cleanup(p.Revoke)
	return p
}
func guardedSet(c *RebindingUDPConn, p nettype.PacketConn) { c.pconn = p; c.pconnAtomic.Store(&p) }
func guardedBuffers() [][]byte {
	return [][]byte{append(make([]byte, packet.GeneveFixedHeaderLength), []byte("synthetic-one")...), append(make([]byte, packet.GeneveFixedHeaderLength), []byte("synthetic-two")...)}
}
func guardedFakeConn(p nettype.PacketConn, policy *underlayguard.Policy) *Conn {
	c := newConn(logger.Discard)
	c.underlayPolicy = policy
	c.metrics = registerMetrics(new(usermetric.Registry))
	c.pconn4.underlayPolicy = policy
	c.pconn6.underlayPolicy = policy
	guardedSet(&c.pconn4, p)
	guardedSet(&c.pconn6, p)
	return c
}
func guardedCalls(c *Conn, ap netip.AddrPort) []func() error {
	return []func() error{
		func() error { _, e := c.sendUDPStd(ap, []byte("synthetic")); return e },
		func() error { _, e := c.sendUDP(ap, []byte("synthetic-disco"), true, false); return e },
		func() error { _, e := c.sendUDPNetcheck([]byte("synthetic-netcheck"), ap); return e },
		func() error {
			_, e := c.sendUDPBatch(epAddr{ap: ap}, guardedBuffers(), packet.GeneveFixedHeaderLength)
			return e
		},
		func() error {
			return c.Send(guardedBuffers(), &lazyEndpoint{c: c, src: epAddr{ap: ap}}, packet.GeneveFixedHeaderLength)
		},
	}
}

