		c := guardedFakeConn(first, policy)
		revoked := make(chan struct{})
		revoke := func() error {
			guardedSet(&c.pconn4, next)
			go func() { policy.Revoke(); close(revoked) }()
			deadline := time.Now().Add(time.Second)
			for !errors.Is(policy.Validate(), underlayguard.ErrRevoked) {
				if time.Now().After(deadline) {
					t.Fatal("revocation not started")
				}
				runtime.Gosched()
			}
			return net.ErrClosed
		}
		first.onWrite = revoke
		first.onBatch = revoke
		ap := netip.MustParseAddrPort("10.25.0.3:3000")
		var err error
		if fast {
			err = c.pconn4.WriteWireGuardBatchTo(guardedBuffers(), epAddr{ap: ap}, packet.GeneveFixedHeaderLength)
		} else {
			_, err = c.pconn4.WriteToUDPAddrPort(nil, ap)
		}
		<-revoked
		if !errors.Is(err, underlayguard.ErrRevoked) || next.writes != 0 || next.batches != 0 {
			t.Fatal("retry escaped revoked policy", err)
		}
	}
